def transform(grid):
    h, w = len(grid), len(grid[0])
    anchors = {r: row[0] for r, row in enumerate(grid) if row[0] != 0}
    if not anchors:
        return [row[:] for row in grid]
    # Find shortest period consistent with all nonzero full-row anchors.
    p = next(p for p in range(1, h + 1) if all(
        a % p != b % p or anchors[a] == anchors[b]
        for a in anchors for b in anchors))
    motif = {r % p: v for r, v in anchors.items()}
    known = sorted(motif)
    for k in range(p):
        if k not in motif:
            prev = [j for j in known if j < k]
            motif[k] = motif[prev[-1]] if prev else motif[known[-1]]
    return [[motif[r % p]] * w for r in range(h)]

